import base64
import datetime
import hashlib
import json
import pathlib
import subprocess
import tempfile
import time

root = pathlib.Path('/repos/Antigravity/typst-crystalline')
destination = root / '00_nucleo/diagnosticos/p1306-planning-measurement.json'
assert not destination.exists()
binary_specs = {
    'vanilla': ('/usr/local/bin/typst', '7b4f40c56d6fa95082ebcfd893e275d418ebcaed1b97b62785f78284c63ff7b8'),
    'crystalline': ('/dev/shm/p1305-r2-target.F7bquUC2/release/typst', 'be51045f1df75ac42ee081801ddf7f738f709029e3694b9205473ba5fa8b31d4'),
}
profiles = {'default': [], 'html': ['html'], 'a11y': ['a11y-extras'], 'html+a11y': ['html', 'a11y-extras']}
fixtures = {'ordinary/std.typ': '#let x = 7\n', 'ordinary/map.typ': '#let x = 9\n', 'reexport/std.typ': '#import std: *\n'}
probes = {
    'ordinary-std-missing': '{ import "ordinary/std.typ" as m; m.nope }',
    'ordinary-std-alias-missing': '{ import "ordinary/std.typ" as m; let alias = m; alias.absent }',
    'reexport-std-missing': '{ import "reexport/std.typ" as m; m.nope }',
    'ordinary-map-missing': '{ import "ordinary/map.typ" as m; m.nope }',
    'global-missing': 'std.nope',
    'global-alias-missing': '{ let alias = std; alias.nope }',
    'ordinary-std-positive': '{ import "ordinary/std.typ" as m; (repr(m), m.x) }',
    'reexport-std-positive': '{ import "reexport/std.typ" as m; (repr(m), m.calc.abs(-7)) }',
}
def git(*args):
    return subprocess.check_output(['git', *args], cwd=root).decode()

def state():
    return {'head': git('rev-parse', 'HEAD').strip(), 'status': git('status', '--short'), 'diff_stat': git('diff', 'HEAD', '--stat'), 'diff_sha256': hashlib.sha256(subprocess.check_output(['git', 'diff', 'HEAD', '--binary'], cwd=root)).hexdigest()}

before = state()
binary_pins = {}
for side, (path, expected) in binary_specs.items():
    raw = pathlib.Path(path).read_bytes()
    actual = hashlib.sha256(raw).hexdigest()
    assert actual == expected, (side, actual)
    binary_pins[side] = {'path': path, 'sha256': actual, 'bytes': len(raw)}
work = pathlib.Path(tempfile.mkdtemp(prefix='p1306-planning-'))
for relative, source in fixtures.items():
    path = work / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source)
rows = []
jobs = [(key, profile) for key in probes for profile in profiles]
for phase, ordered, sides in [('normal', jobs, list(binary_specs)), ('inverted', jobs[::-1], list(binary_specs)[::-1])]:
    for key, profile in ordered:
        for side in sides:
            argv = [binary_specs[side][0], 'eval', probes[key], '--format', 'json']
            if profiles[profile]:
                argv += ['--features', ','.join(profiles[profile])]
            started = datetime.datetime.now(datetime.timezone.utc).isoformat()
            clock = time.monotonic_ns()
            result = subprocess.run(argv, cwd=work, capture_output=True, timeout=30)
            row = {'id': key, 'profile': profile, 'phase': phase, 'side': side, 'argv': argv, 'cwd': str(work), 'started_at': started, 'duration_ns': time.monotonic_ns()-clock, 'exit_code': result.returncode}
            for name, raw in [('stdout', result.stdout), ('stderr', result.stderr)]:
                row[name] = raw.decode()
                row[name+'_sha256'] = hashlib.sha256(raw).hexdigest()
                row[name+'_base64'] = base64.b64encode(raw).decode()
            rows.append(row)
source = pathlib.Path(__file__).read_text()
report = {'schema': 'p1306-planning-measurement-v1', 'purpose': 'Read-only measurement to choose and write step1306; not implementation, independent oracle, RED or certificate.', 'source_before': before, 'source_after': state(), 'binary_pins': binary_pins, 'binary_source_relation': 'Pinned crystalline binary built and certified before commit b303f1f15; commit only consolidates identical source and historical evidence. Use source pins in p1305-r2-certificate.json, not version string.', 'fixtures': fixtures, 'probes': probes, 'profiles': profiles, 'runs': rows, 'runner_source': source, 'runner_sha256': hashlib.sha256(source.encode()).hexdigest()}
destination.write_text(json.dumps(report, indent=2, ensure_ascii=False)+'\n')
normal = {(r['id'],r['profile'],r['side']):r for r in rows if r['phase']=='normal'}
stable = all(all(r[k]==normal[(r['id'],r['profile'],r['side'])][k] for k in ['exit_code','stdout','stderr']) for r in rows if r['phase']=='inverted')
print(json.dumps({'path': str(destination), 'sha256': hashlib.sha256(destination.read_bytes()).hexdigest(), 'runs': len(rows), 'stable': stable, 'source': before}))
for key in probes:
    print(key, [(side, normal[(key,'default',side)]['exit_code'], normal[(key,'default',side)]['stderr'].splitlines()[:1], normal[(key,'default',side)]['stdout'].strip()) for side in binary_specs])
